from __future__ import annotations

from twitter import models
from twitter.storage import InMemoryStore


class FanoutService:
    def __init__(
        self,
        store: InMemoryStore,
        celebrity_threshold: int = models.DEFAULT_CELEBRITY_THRESHOLD,
    ) -> None:
        self._store = store
        self._celebrity_threshold = celebrity_threshold

    def fanout_tweet(self, tweet: models.Tweet) -> None:
        author = self._store.get_user(tweet.user_id)
        if author is None:
            return

        if author.is_celebrity(self._celebrity_threshold):
            self._celebrity_fanout(tweet, author)
        else:
            self._normal_fanout(tweet, author)

    def _normal_fanout(self, tweet: models.Tweet, author: models.User) -> None:
        followers = self._store.get_followers(author.id)
        for follower_id in followers:
            entry = models.TimelineEntry(
                user_id=follower_id,
                tweet_id=tweet.id,
                author_id=author.id,
                created_at=tweet.created_at,
            )
            self._store.push_timeline_entry(follower_id, entry)

    def _celebrity_fanout(self, tweet: models.Tweet, author: models.User) -> None:
        pass

    def get_celebrity_threshold(self) -> int:
        return self._celebrity_threshold

from __future__ import annotations

from twitter import models
from twitter.storage import InMemoryStore


class SearchService:
    def __init__(self, store: InMemoryStore) -> None:
        self._store = store

    def index_tweet(self, tweet: models.Tweet) -> None:
        tokens = set(models._tokenize(tweet.content))
        for token in tokens:
            self._store.add_to_index(token, tweet.id)

    def search(self, query: str, limit: int = 20) -> list[models.Tweet]:
        query_tokens = set(models._tokenize(query))
        if not query_tokens:
            return []

        candidate_sets: list[set[str]] = []
        for token in query_tokens:
            entries = self._store.get_index_entries(token)
            candidate_sets.append(set(entries))

        if not candidate_sets:
            return []

        matching_ids = candidate_sets[0]
        for cs in candidate_sets[1:]:
            matching_ids = matching_ids & cs

        tweets: list[models.Tweet] = []
        for tweet_id in matching_ids:
            tweet = self._store.get_tweet(tweet_id)
            if tweet is not None:
                tweets.append(tweet)

        tweets.sort(key=lambda t: t.created_at, reverse=True)
        return tweets[:limit]

    def reindex_tweet(self, tweet: models.Tweet) -> None:
        pass

